function revenueLabel407(value){return value==null||value===''?'Unknown':String(value)}
function renderAgencyMap407(rows){return Array.isArray(rows)?rows:[]}
function renderTrendStrip407(rows){return Array.isArray(rows)?rows:[]}
function uniqueAttention407(rows){
  const seen=new Set();
  return (Array.isArray(rows)?rows:[]).filter(item=>{
    const key=[item.client||'Company',item.reason||item.title||'',item.evidence||item.source_type||'',item.next_action||''].map(value=>String(value).trim().toLowerCase()).join('|');
    if(seen.has(key))return false;
    seen.add(key);return true;
  });
}
