    async function renderSignals407(){const target=$('system-modules');target.innerHTML=honestState('loading','Loading signals','Reading routed signals from the permitted workspace.');try{const data=await api(`/signals?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`),items=data.signals||[];target.innerHTML=`<section class="card module" style="grid-column:1/-1"><span class="state">Canonical · ${items.length} records</span><h2 style="margin-top:9px">Inbox / Signals</h2><p class="sub">Signals are evidence inputs, not automatic decisions. Review source and status before acting.</p><div class="module-grid">${items.map(item=>`<article class="card module"><span class="state ${item.status==='open'?'':'off'}">${esc(item.status||'Unknown')}</span><h2 style="margin-top:9px">${esc(item.type||'Signal')}</h2><ul><li>Evidence: ${esc(item.evidence||'Unknown')}</li><li>Source: ${esc(item.source_type||item.source_id||'Unknown')}</li><li>Confidence: ${esc(item.confidence??'Unknown')}</li><li>Created: ${esc(item.created_at||'Unknown')}</li></ul></article>`).join('')||honestState('empty','No signals recorded','The permitted workspace has no routed signals yet.')}</div></section>`}catch(error){target.innerHTML=honestState('degraded','Signals unavailable',error.message,'renderSignals407')}}
    function performanceKpis407(campaigns){const sum=key=>{const values=campaigns.map(item=>Number(item[key])).filter(Number.isFinite);return values.length?values.reduce((a,b)=>a+b,0):null},revenue=sum('revenue'),spend=sum('spend'),leads=sum('leads'),impressions=sum('impressions'),clicks=sum('clicks'),roas=revenue!=null&&spend?revenue/spend:null,ctr=impressions&&clicks!=null?clicks/impressions*100:null;return `<section class="card module" style="grid-column:1/-1"><h3>Agency performance KPIs</h3><div class="module-grid">${[['Attributed revenue',revenue==null?'Unknown':revenue],['ROAS',roas==null?'Unknown':roas.toFixed(2)],['Leads',leads==null?'Unknown':leads],['CTR',ctr==null?'Unknown':`${ctr.toFixed(1)}%`],['Spend',spend==null?'Unknown':spend],['CVR','Unknown']].map(([label,value])=>`<article class="card module"><span class="source-note">${label}</span><p class="metric-value">${esc(value)}</p></article>`).join('')}</div><p class="source-note">Aggregates use only numeric campaign snapshots returned by /dashboard/performance; missing provider metrics remain Unknown.</p></section>`}
    async function renderPerformance407(){const target=$('system-modules');target.innerHTML=honestState('loading','Loading performance','Reading campaign and creative metrics from the permitted workspace.');try{const data=await api(`/dashboard/performance?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`),campaigns=data.campaigns||[],insights=data.insights||[],creative=data.creative_comparison||[];target.innerHTML=`<section class="card module" style="grid-column:1/-1"><span class="state">Canonical · ${esc(data.evidence_status||'unknown')}</span><h2 style="margin-top:9px">Performance</h2><p class="sub">Metrics remain unknown when no connected source is available. No values are fabricated.</p><div class="module-grid"><article class="card module"><h3>Campaigns</h3><p class="metric-value">${campaigns.length}</p><p class="sub">${campaigns.length?'Sourced campaigns':'Unknown — no campaign metrics returned'}</p></article><article class="card module"><h3>Insights</h3><p class="metric-value">${insights.length}</p><p class="sub">${insights.length?'Evidence-backed insights':'No performance insights recorded'}</p></article><article class="card module"><h3>Creative comparison</h3><p class="metric-value">${creative.length}</p><p class="sub">${creative.length?'Sourced creative samples':'Unknown — no connected creative metrics'}</p></article></div>${campaigns.length?`<table class="dense-table"><thead><tr><th>Campaign</th><th>Status</th><th>Spend</th><th>Revenue</th><th>ROAS</th></tr></thead><tbody>${campaigns.map(item=>`<tr><td>${esc(item.name||'Campaign')}</td><td>${esc(item.status||'Unknown')}</td><td>${esc(item.spend??'Unknown')}</td><td>${esc(item.revenue??'Unknown')}</td><td>${esc(item.roas??'Unknown')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No connected campaign metrics are available in this workspace.</div>'}</section>`;target.insertAdjacentHTML('beforeend',performanceKpis407(campaigns))}catch(error){target.innerHTML=honestState('degraded','Performance unavailable',error.message,'renderPerformance407')}}
    async function renderReports407(){const target=$('system-modules');target.innerHTML=honestState('loading','Loading reports','Reading report runs from the permitted workspace.');try{const data=await api(`/reports?organization_id=${encodeURIComponent(org)}&person_id=${encodeURIComponent(person)}`),items=data.reports||[];target.innerHTML=`<section class="card module" style="grid-column:1/-1"><div class="row" style="justify-content:space-between;align-items:center"><div><span class="state">Canonical · ${items.length} records</span><h2 style="margin-top:9px">Reports</h2><p class="sub">Generate a report run through the authenticated report service. Results remain queued until a worker completes them.</p></div>${canOperateWorkspace()?'<button class="action" type="button" data-report-generate>Generate report</button>':'<span class="state off">Read only</span>'}</div><div class="module-grid">${items.map(item=>`<article class="card module"><span class="state">${esc(item.report_type||item.type||'unknown')}</span><h3>${esc(item.name||'Report run')}</h3><p class="sub">${esc(item.created_at||item.started_at||'Unknown timestamp')} · ${esc(item.id||'No run id')}</p></article>`).join('')||'<div class="empty">No report runs have been recorded.</div>'}</div></section>`;const button=target.querySelector('[data-report-generate]');if(button)button.onclick=async()=>{const reportType=window.prompt('Report type','executive');if(!reportType)return;button.disabled=true;try{await api('/reports/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organization_id:org,person_id:person,workspace_id:workspace,type:reportType.trim(),report_type:reportType.trim()})});toast('Report queued for worker processing');renderReports407()}catch(error){button.disabled=false;toast(`Report unavailable · ${error.message}`)}}}catch(error){target.innerHTML=honestState('degraded','Reports unavailable',error.message,'renderReports407')}}
    async function renderAutomations407(){const target=$('system-modules');target.innerHTML=honestState('loading','Loading automations','Reading automation records and approval policy.');try{const data=await api(`/automations?organization_id=${encodeURIComponent(org)}&person_id=${encodeURIComponent(person)}`),items=data.automations||[];target.innerHTML=`<section class="card module" style="grid-column:1/-1"><span class="state">Canonical · ${items.length} records</span><h2 style="margin-top:9px">Automations</h2><p class="sub">Activation and triggering are explicit actions. Training and human-approval policies remain visible before any run is queued.</p><div class="module-grid">${items.map(item=>{const active=['active','enabled'].includes(String(item.status||'').toLowerCase()),policy=item.approval_policy||'human';return `<article class="card module"><span class="state ${active?'':'off'}">${esc(item.status||'unknown')}</span><h3>${esc(item.name||item.id||'Automation')}</h3><ul><li>Trigger: ${esc(item.trigger_type||'Unknown')}</li><li>Approval: ${esc(policy)}</li><li>Training: ${esc(item.training_state||'Not reported')}</li></ul><div class="row">${canOperateWorkspace()&&!active?`<button class="ghost" type="button" data-automation-activate="${esc(item.id)}">Activate</button>`:''}${canOperateWorkspace()&&active?`<button class="action" type="button" data-automation-trigger="${esc(item.id)}" data-trigger-type="${esc(item.trigger_type||'manual')}">Trigger</button>`:''}</div></article>`}).join('')||'<div class="empty">No automations are configured for this organization.</div>'}</div></section>`;target.querySelectorAll('[data-automation-activate]').forEach(button=>button.onclick=async()=>{if(!window.confirm('Activate this automation? It will remain subject to its approval policy.'))return;button.disabled=true;try{await api('/automations/activate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organization_id:org,person_id:person,automation_id:button.dataset.automationActivate})});toast('Automation activated');renderAutomations407()}catch(error){button.disabled=false;toast(`Activation unavailable · ${error.message}`)}});target.querySelectorAll('[data-automation-trigger]').forEach(button=>button.onclick=async()=>{if(!window.confirm('Queue this automation trigger for worker processing?'))return;button.disabled=true;try{await api('/automations/trigger',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organization_id:org,trigger_type:button.dataset.triggerType,payload:{automation_id:button.dataset.automationTrigger,workspace_id:workspace}})});toast('Automation trigger queued; approval policy still applies');renderAutomations407()}catch(error){button.disabled=false;toast(`Trigger unavailable · ${error.message}`)}})}catch(error){target.innerHTML=honestState('degraded','Automations unavailable',error.message,'renderAutomations407')}}
    async function renderIntegrations407(){const target=$('system-modules');target.innerHTML=honestState('loading','Loading integrations','Reading credential and connection state.');try{const data=await api(`/integrations?organization_id=${encodeURIComponent(org)}`),items=data.integrations||[];target.innerHTML=`<section class="card module" style="grid-column:1/-1"><span class="state">Canonical · ${items.length} connectors</span><h2 style="margin-top:9px">Integrations</h2><p class="sub">No credentials are shown here. Verify and Sync appear only when a canonical live connector is authorized.</p><div class="module-grid">${items.map(item=>{const status=String(item.status||'not_connected').toLowerCase(),credential=item.credential||{},ready=['authorized','connected'].includes(status)&&item.live_enabled&&credential.status!=='missing';return `<article class="card module"><span class="state ${ready?'':'off'}">${esc(status)}</span><h3>${esc(item.source||item.id||'Integration')}</h3><ul><li>Credential: ${esc(credential.status||'not connected')}</li><li>Health: ${esc(item.health||'unknown')}</li><li>Last sync: ${esc(item.last_sync_at||'Never')}</li><li>Objects: ${esc(item.object_count??'Unknown')}</li></ul><div class="row">${ready?`<button class="ghost" type="button" data-integration-verify="${esc(item.id)}">Verify</button><button class="action" type="button" data-integration-sync="${esc(item.id)}">Sync</button>`:'<span class="source-note">Not connected — add and verify credentials before syncing.</span>'}</div></article>`}).join('')||'<div class="empty">No connector records are configured. Add credentials to activate an integration.</div>'}</div></section>`;target.querySelectorAll('[data-integration-verify]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api('/integrations/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({integration_id:button.dataset.integrationVerify})});toast('Integration verified');renderIntegrations407()}catch(error){button.disabled=false;toast(`Verification unavailable · ${error.message}`)}});target.querySelectorAll('[data-integration-sync]').forEach(button=>button.onclick=async()=>{if(!window.confirm('Queue a sync for this integration?'))return;button.disabled=true;try{await api('/integrations/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({integration_id:button.dataset.integrationSync})});toast('Sync queued for worker processing');renderIntegrations407()}catch(error){button.disabled=false;toast(`Sync unavailable · ${error.message}`)}})}catch(error){target.innerHTML=honestState('degraded','Integrations unavailable',error.message,'renderIntegrations407')}}
