    function enhanceAccessDialog407(dialog,message){
      if(!dialog)return;const form=dialog.querySelector('form'),note=dialog.querySelector('[data-auth-message]');if(note)note.textContent=message||'This temporary access token is your sign-in key. Your administrator creates it during agency setup; it is stored only in this browser and should never be shared.';
      if(!form)return;let help=form.querySelector('[data-auth-help]');if(!help){help=document.createElement('p');help.className='sub';help.dataset.authHelp='1';help.textContent='First activation: an administrator should run setup-agency and give each operator a token. Existing local operators can use bootstrap-auth to issue a replacement. Tokens stay in this browser and should never be shared.';form.querySelector('label')?.insertAdjacentElement('afterend',help)}let error=form.querySelector('[data-auth-error]');if(!error){error=document.createElement('p');error.className='auth-error';error.dataset.authError='1';form.querySelector('.row')?.insertAdjacentElement('beforebegin',error)}form.onsubmit=async event=>{event.preventDefault();const token=String(new FormData(form).get('token')||'').trim();if(!token){error.textContent='Paste an access token to continue.';return}const connect=form.querySelector('button[type="submit"]');if(connect)connect.disabled=true;error.textContent='Checking token…';localStorage.setItem('auremgrid_session',token);try{const response=await fetch('/auth/me');if(!response.ok){let detail='Token rejected. Ask your administrator for a current token.';try{const payload=await response.json();detail=payload.message||detail}catch(_){ }throw new Error(detail)}window.location.reload()}catch(err){localStorage.removeItem('auremgrid_session');error.textContent=err.message;form.querySelector('input[name="token"]').focus();if(connect)connect.disabled=false}};
    }
